css:
.layout {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 16px;
  min-height: 320px;
  padding: 12px;
}

.sidebar {
  padding: 12px;
  background: #18181b;
  color: #fafafa;
  border-radius: 6px;
}

.menu {
  margin: 0;
  padding-left: 16px;
}

.content {
  min-width: 0;
  padding: 12px;
  background: #fed7aa;
  border: 1px solid #f97316;
  border-radius: 6px;
}

@media (max-width: 520px) {
  .layout {
    grid-template-columns: 1fr;
  }
}
